package com.brightloop.discount;
import jakarta.validation.Valid;import jakarta.validation.constraints.*;import java.math.BigDecimal;import java.time.LocalDate;import org.springframework.http.HttpStatus;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;
@RestController @RequestMapping("/api/discounts") @PreAuthorize("hasRole('ADMIN')") public class DiscountController {
 private final DiscountRepository repo;public DiscountController(DiscountRepository r){repo=r;}
 public record Request(@NotBlank @Size(max=40) String code,@NotBlank String name,@Pattern(regexp="PERCENTAGE|FIXED") String discountType,@NotNull @DecimalMin("0.0001") BigDecimal value,LocalDate startsAt,LocalDate endsAt,@Min(1) Integer maxUses,boolean active){}
 public record Response(Long id,String code,String name,String discountType,BigDecimal value,LocalDate startsAt,LocalDate endsAt,Integer maxUses,int usageCount,boolean active){static Response of(Discount d){return new Response(d.getId(),d.getCode(),d.getName(),d.getDiscountType(),d.getValue(),d.getStartsAt(),d.getEndsAt(),d.getMaxUses(),d.getUsageCount(),d.isActive());}}
 @GetMapping public java.util.List<Response> list(){return repo.findAll().stream().map(Response::of).toList();}
 @PostMapping @ResponseStatus(HttpStatus.CREATED) public Response create(@Valid @RequestBody Request r){if(repo.existsByCodeIgnoreCase(r.code()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Discount code already exists");return Response.of(repo.save(new Discount(r.code(),r.name(),r.discountType(),r.value(),r.startsAt(),r.endsAt(),r.maxUses(),r.active())));}
 @PutMapping("/{id}") public Response update(@PathVariable Long id,@Valid @RequestBody Request r){var d=repo.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Discount not found"));if(repo.existsByCodeIgnoreCaseAndIdNot(r.code(),id))throw new ResponseStatusException(HttpStatus.CONFLICT,"Discount code already exists");d.code=r.code().toUpperCase().trim();d.update(r.name(),r.discountType(),r.value(),r.startsAt(),r.endsAt(),r.maxUses(),r.active());return Response.of(d);}
 @DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable Long id){repo.delete(repo.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Discount not found")));}
}
